# 注册中文字体（使用系统自带字体）
def register_chinese_fonts():
    """注册中文字体"""
    try:
        # macOS系统字体
        pdfmetrics.registerFont(TTFont('STSong', '/System/Library/Fonts/STHeiti Light.ttc'))
        pdfmetrics.registerFont(TTFont('STFangsong', '/System/Library/Fonts/STFangsong.ttf'))
        return True
    except:
        try:
            # 备用字体路径
            pdfmetrics.registerFont(TTFont('STSong', '/System/Library/Fonts/PingFang.ttc'))
            return True
        except:
            return False

